import styled from "styled-components";
import { useState, useEffect, useContext } from "react";
import { ExternalLink } from "react-external-link";
import { Contexte } from "../Contexte";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCircleCheck } from "@fortawesome/free-solid-svg-icons";

const EtatMetro = () => {
  const { etatDuMetro, setEtatDuMetro } = useContext(Contexte);
  const [toutBien, setToutBien] = useState(true);

  useEffect(() => {
    obtenirEtatMetro();
  }, []);

  const obtenirEtatMetro = async () => {
    try {
      const response = await fetch(
        "https://api.stm.info/pub/od/i3/v2/messages/etatservice",
        {
          method: "GET",
          headers: {
            apiKey: "l72510e154f74447ff93902ccafbe2a111",
            Accept: "application/json",
          },
        },
      );
      if (!response.ok) {
        throw new Error(`Erreur API: ${response.status}`);
      }
      const data = await response.json();
      let dataMetro = [];
      for (
        let index = data.alerts.length - 4;
        index < data.alerts.length;
        index++
      ) {
        const element = data.alerts[index];
        dataMetro.push({
          ligne: element.informed_entities[0].route_short_name,
          etat: element.description_texts[0].text,
        });
      }
      const lignesTriees = dataMetro.sort((a, b) =>
        a.ligne.localeCompare(b.ligne, undefined, { numeric: true }),
      );
      setEtatDuMetro(lignesTriees);
      console.log(lignesTriees);
      let feuVert = lignesTriees.every(
        element => element.etat === "Service normal du métro"
      );
      setToutBien(feuVert)
      
    } catch (error) {
      console.error("Erreur STM:", error);
    }
  };

  if (etatDuMetro !== undefined) {
    return (
      <Container>
        {
          toutBien
          ? <p><FontAwesomeIcon icon={faCircleCheck} /><span> Le métro fonctionne normalement.</span></p>
          : etatDuMetro.map((ligne, index) => {
          return (
            <p key={index}>
              Ligne {ligne.ligne} : {ligne.etat}
            </p>
          );
        })}
        <p><ExternalLink href="https://www.stm.info/horaires-et-trajets/metro?showAccessibility=true">Voir l'état des ascenseurs et des escaliers mécaniques</ExternalLink></p>
        <p><ExternalLink href="https://rem.info/fr/se-deplacer/etat-du-service">État du service du REM</ExternalLink></p>
      </Container>
    );
  }
};

const Container = styled.section`
  background-color: var(--u1a);
  margin: 0;
  padding: 15px 0;
  a, p {
    color: var(--c0);
  }
`;

export default EtatMetro;
